import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = rb();
        while (c != '-' && (c < '0' || c > '9')) c = rb();
        boolean neg = c == '-';
        if (neg) c = rb();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = rb();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }


    public static void main(String[] args) throws IOException {
        int n = nextInt();
        // Keyed by original duration: the time the group's next task will take.
        HashMap<Long, Long> nextTime = new HashMap<>(2 * n);
        long total = 0;
        for (int i = 0; i < n; i++) {
            long original = nextLong();
            long value = nextTime.getOrDefault(original, original);
            total += value;
            nextTime.put(original, (value + 1) / 2);
        }
        System.out.println(total);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	n := 0
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}


func main() {
	n := readInt()
	// Keyed by original duration: the time the group's next task will take.
	nextTime := make(map[int]int, n)
	total := 0
	for i := 0; i < n; i++ {
		original := readInt()
		value, ok := nextTime[original]
		if !ok {
			value = original
		}
		total += value
		nextTime[original] = (value + 1) / 2
	}
	fmt.Println(total)
}
